definitions.definition:
pub struct CaretMark { pub line: u32, pub byte: usize }

pub struct SelSpan { pub line: u32, pub start_byte: usize, pub end_byte: usize }

/// UTF-8 byte offset of char column `col` in one line. Same sum as paint::byte_at_char.
pub fn line_byte(line: &str, col: u32) -> usize

/// One mark per selection head. `byte` is line_byte of that line.
pub fn caret_marks(buf: &kate_text::TextBuffer, selections: &kate_core::Selections) -> Vec<CaretMark>

/// Half-open UTF-8 spans for non-caret selections. A caret adds no span.
/// A span stays on one line. The newline belongs to the line that ends there.
pub fn selection_spans(buf: &kate_text::TextBuffer, selections: &kate_core::Selections) -> Vec<SelSpan>

/// Empty text returns None. Any other text returns Command::InsertText of that text.
/// Newlines in the committed string stay in the command.
pub fn command_for_commit(text: &str) -> Option<kate_core::Command>

/// None when the binding is not in the table.
pub fn command_for_binding(binding: &str) -> Option<kate_core::Command>

/// Return the first visible line that keeps the caret inside the window.
/// visible_rows of 0 leaves first_line unchanged.
/// A caret above the window moves the window to that line.
/// A caret below the window uses caret_line + 1 - visible_rows.
/// Clamp the caret to the last line. Clamp the result so the window stays in range.
pub fn reveal_line(first_line: u32, visible_rows: u32, caret_line: u32, line_count: u32) -> u32
